// Generated by an AI assistant. Contains bugs on purpose (Module 4 exercise).

const COLORS = ["#4e79a7", "#f28e2b", "#e15759", "#76b7b2", "#59a14f"];

function render({ model, el }) {
  const toolbar = document.createElement("div");
  toolbar.className = "rld-toolbar";
  const canvas = document.createElement("canvas");
  canvas.width = 800;
  canvas.height = 200;
  canvas.className = "rld-canvas";
  const list = document.createElement("div");
  list.className = "rld-list";
  el.append(toolbar, canvas, list);
  const ctx = canvas.getContext("2d");

  const colorOf = (label) => COLORS[model.get("labels").indexOf(label) % COLORS.length];

  function draw() {
    const t = model.get("t");
    const y = model.get("y");
    const t0 = t[0], t1 = t[t.length - 1];
    const ymin = Math.min(...y), ymax = Math.max(...y);
    const xOf = (v) => ((v - t0) / (t1 - t0)) * canvas.width;
    const yOf = (v) => canvas.height - ((v - ymin) / (ymax - ymin)) * canvas.height;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (const r of model.get("ranges")) {
      ctx.fillStyle = colorOf(r.label);
      ctx.globalAlpha = 0.25;
      ctx.fillRect(xOf(r.start), 0, xOf(r.end) - xOf(r.start), canvas.height);
    }
    ctx.globalAlpha = 1;
    ctx.beginPath();
    for (let i = 0; i < t.length; i++) {
      if (i === 0) ctx.moveTo(xOf(t[i]), yOf(y[i]));
      else ctx.lineTo(xOf(t[i]), yOf(y[i]));
    }
    ctx.stroke();
  }

  function drawToolbar() {
    toolbar.innerHTML = "";
    for (const label of model.get("labels")) {
      const btn = document.createElement("button");
      btn.textContent = label;
      if (label === model.get("active_label")) btn.className = "rld-active";
      btn.onclick = () => {
        model.set("active_label", label);
        model.save_changes();
        drawToolbar();
      };
      toolbar.append(btn);
    }
    const clear = document.createElement("button");
    clear.textContent = "Clear all";
    clear.onclick = () => {
      model.set("ranges", []);
      draw();
      drawList();
    };
    toolbar.append(clear);
  }

  function drawList() {
    list.innerHTML = "";
    for (const r of model.get("ranges")) {
      const chip = document.createElement("span");
      chip.className = "rld-chip";
      chip.innerHTML = `<b>${r.label}</b>: ${r.start.toFixed(2)} to ${r.end.toFixed(2)}`;
      list.append(chip);
    }
  }

  // Drag to create a range.
  let startX = null;
  canvas.addEventListener("mousedown", (e) => {
    startX = e.offsetX;
  });
  canvas.addEventListener("mouseup", (e) => {
    if (startX === null) return;
    const t = model.get("t");
    const t0 = t[0], t1 = t[t.length - 1];
    const toTime = (x) => t0 + (x / canvas.width) * (t1 - t0);
    const a = toTime(Math.min(startX, e.offsetX));
    const b = toTime(Math.max(startX, e.offsetX));
    startX = null;

    const ranges = model.get("ranges");
    ranges.push({ start: a, end: b, label: model.get("active_label") });
    model.set("ranges", ranges);
    model.save_changes();
  });

  model.on("change:ranges", () => {
    draw();
    drawList();
  });

  drawToolbar();
  draw();
  drawList();
}

export default { render };
